using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap a REST API. Uses constructor injection for DI services
/// (HttpClient, ILogger) — these are resolved by the MCP SDK and never appear
/// in the tool schema exposed to LLMs.
/// </summary>
[McpServerToolType]
public class ApiTools(IHttpClientFactory httpClientFactory, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Get a post by its numeric ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The numeric ID of the post (1-100)")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {PostId}", postId);
        var client = httpClientFactory.CreateClient("api");
        var json = await client.GetStringAsync($"/posts/{postId}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts by this user ID. Omit to list all posts.")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        logger.LogInformation("Listing posts from {Url}", url);
        var json = await client.GetStringAsync(url, cancellationToken);

        // Return a summary to keep responses manageable for LLMs
        using var doc = JsonDocument.Parse(json);
        var posts = doc.RootElement.EnumerateArray()
            .Select(p => new
            {
                id = p.GetProperty("id").GetInt32(),
                title = p.GetProperty("title").GetString()
            });
        return JsonSerializer.Serialize(posts, JsonOptions);
    }

    [McpServerTool, Description("Get all comments for a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to retrieve comments for")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching comments for post {PostId}", postId);
        var client = httpClientFactory.CreateClient("api");
        var json = await client.GetStringAsync($"/posts/{postId}/comments", cancellationToken);
        return json;
    }

    [McpServerTool(ReadOnly = true), Description("Search posts by keyword in title or body.")]
    public async Task<string> SearchPosts(
        [Description("Keyword to search for in post titles and bodies")] string keyword,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("api");
        var json = await client.GetStringAsync("/posts", cancellationToken);

        using var doc = JsonDocument.Parse(json);
        var matches = doc.RootElement.EnumerateArray()
            .Where(p =>
                (p.GetProperty("title").GetString()?.Contains(keyword, StringComparison.OrdinalIgnoreCase) ?? false) ||
                (p.GetProperty("body").GetString()?.Contains(keyword, StringComparison.OrdinalIgnoreCase) ?? false))
            .Select(p => new
            {
                id = p.GetProperty("id").GetInt32(),
                title = p.GetProperty("title").GetString()
            });

        return JsonSerializer.Serialize(matches, JsonOptions);
    }
}

